        return isinstance(v, (int, float))

    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pair(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
            return obj[0], obj[1]
        if isinstance(obj, dict):
            x = obj.get("x")
            y = obj.get("y")
            if is_num(x) and is_num(y):
                return x, y
        return default

    def move_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def move_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def extract_positions(value):
        out = []
        if isinstance(value, dict):
            for k in ("positions", "cells", "items", "targets", "resources", "points"):
                if k in value:
                    value = value.get(k)
                    break
        if isinstance(value, (list, tuple)):
